# Convert to words
def num_to_words(n):
    ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
            'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
            'seventeen', 'eighteen', 'nineteen']
    tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

    def helper(n):
        if n == 0:
            return ''
        elif n < 20:
            return ones[n]
        elif n < 100:
            return tens[n//10] + ((' ' + ones[n%10]) if n%10 else '')
        elif n < 1000:
            return ones[n//100] + ' hundred' + ((' ' + helper(n%100)) if n%100 else '')
        elif n < 1_000_000:
            return helper(n//1000) + ' thousand' + ((' ' + helper(n%1000)) if n%1000 else '')
        elif n < 1_000_000_000:
            return helper(n//1_000_000) + ' million' + ((' ' + helper(n%1_000_000)) if n%1_000_000 else '')
        elif n < 1_000_000_000_000:
            return helper(n//1_000_000_000) + ' billion' + ((' ' + helper(n%1_000_000_000)) if n%1_000_000_000 else '')
        else:
            return helper(n//1_000_000_000_000) + ' trillion' + ((' ' + helper(n%1_000_000_000_000)) if n%1_000_000_000_000 else '')

    if n == 0:
        return 'zero'
    return helper(n)

print("In words:", num_to_words(remainder))
